// Measure distance and light LD2 when something is near
const int TRIG_PIN = 7;            // D7 = PA8
const int ECHO_PIN = 8;            // D8 = PA9, 5 V tolerant, so ECHO goes in directly
const long NEAR_CM = {{p:near}};   // closer than this lights LD2

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  digitalWrite(TRIG_PIN, HIGH);    // a 10 µs pulse sends the burst
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  // ECHO stays HIGH for the round trip: 58 µs per cm
  long cm = pulseIn(ECHO_PIN, HIGH, 30000) / 58;
  bool near = cm > 0 && cm < NEAR_CM;
  digitalWrite(LED_BUILTIN, near ? HIGH : LOW);
  Serial.print(cm);
  Serial.println(near ? " cm NEAR" : " cm");
  delay({{p:every}});
}

